interface FilterOptions {
  excludeIds?: string[];
  excludeNames?: string[];
  gender?: 'boy' | 'girl' | 'unisex' | 'all';
  language?: string | string[];
  meaningSearch?: string;
  popularOnly?: boolean;
  celebrityOnly?: boolean;
  trendingTop?: number; // e.g. 10, 50, 100 — filters by yearRank
  firstLetter?: string; // single A-Z letter — filters names by first letter
}

export const getRandomNames = (count: number, options: FilterOptions = {}): BabyName[] => {
  const { excludeIds = [], excludeNames = [], gender = 'all', language = 'All', meaningSearch, popularOnly, celebrityOnly, trendingTop, firstLetter } = options;

  let filtered = rawData.filter((item) => !excludeIds.includes(item.id));

  // Exclude by name string for cross-view dedup
  if (excludeNames.length > 0) {
    const nameSet = new Set(excludeNames.map(n => n.toLowerCase()));
    filtered = filtered.filter((item) => !nameSet.has(item.name.toLowerCase()));
  }

  if (gender !== 'all') {
    filtered = filtered.filter((item) => item.gender === gender);
  }

  // Multi-language support
  if (Array.isArray(language)) {
    if (!language.includes('All') && language.length > 0) {
      filtered = filtered.filter((item) => language.includes(item.language));
    }
  } else if (language && language !== 'All') {
    filtered = filtered.filter((item) => item.language === language);
  }

  // Fuzzy multi-field search with synonyms
  if (meaningSearch && meaningSearch.trim()) {
    const words = meaningSearch.toLowerCase().trim().split(/\s+/).filter(w => w.length > 1);
    if (words.length > 0) {
      // Expand words with synonyms
      const expanded = new Set<string>();
      for (const word of words) {
        expanded.add(word);
        const syns = SYNONYMS[word];
        if (syns) syns.forEach(s => expanded.add(s));
      }
      const searchTerms = [...expanded];

      // Score each name by how many search terms match across meaning, origin, and name
      const scored = filtered.map((item) => {
        const fields = `${item.meaning} ${item.origin} ${item.name}`.toLowerCase();
        let score = 0;
        for (const term of searchTerms) {
          if (fields.includes(term)) {
            // Direct word match scores higher than synonym match
            score += words.includes(term) ? 2 : 1;
          }
        }
        return { item, score };
      });
      // Keep only names that match at least one term, sort by score descending
      filtered = scored
        .filter(s => s.score > 0)
        .sort((a, b) => b.score - a.score)
        .map(s => s.item);
    }
  }

  // Popular only
  if (popularOnly) {
    filtered = filtered.filter((item) => item.popularity === 'popular');
  }

  // Celebrity only
  if (celebrityOnly) {
    filtered = filtered.filter((item) => !!item.celebrity);
  }

  // Trending top N (by SSA yearRank)
  if (trendingTop) {
    filtered = filtered.filter((item) => item.yearRank !== undefined && item.yearRank <= trendingTop);
  }

  // First-letter filter (A-Z)
  if (firstLetter && firstLetter.trim()) {
    const letter = firstLetter.trim().toUpperCase();
    filtered = filtered.filter((item) => item.name.charAt(0).toUpperCase() === letter);
  }

  // Shuffle
  const shuffled = filtered.sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count);
};
